style.css:
@-moz-document domain("roblox.com") {
.dark-theme .profile-avatar-left {
      background-color: #000;
  }
  .bg-action-standard {
    background-color: rgba(71, 71, 71, 0.12);
  }
  .bg-surface-300 {
    background-color: #ffffff1f;
  }
  .bg-surface-0 {
    background-color: #000000b5;
  }
  .web-blox-css-mui-16xdy8q {
      background-color: rgba(0, 0, 0, 0.3) !important;
  }
  .profile-avatar-left .enable-three-dee {
      background-color: #000 !important;
      color: #fff !important;
  }
  .dark-theme #catalog-react-page .search-bars {
      background: #000 !important;
  }
  #topic-carousel {
      background-color: #0b0b0b !important;
  }
  .dark-theme .topic-container .topic-carousel .unselected-topic {
      background-color: hsl(0deg 0% 10.38%) !important;
      color: #bdbebe !important;
  }
  .dark-theme .btn-generic-slideshow-xs,
  .dark-theme .btn-generic-grid-xs {
      background-color: rgba(0, 0, 0, 0.3) !important;
      border-color: rgba(255, 255, 255, 0.7) !important;
  }
  .dark-theme .btn-growth-md {
      background-color: #000 !important;
      border-color: #fff !important;
      color: #fff !important;
      border-radius: 8px !important;
  }
  .dark-theme .btn-alert-md {
      background-color: transparent !important;
      border-color: #4f191b !important;
      color: #ab363b !important;
      border-radius: 8px !important;
  }
  #reputationDiv {
      filter: grayscale(1) !important;
  }
  .btr-profile #roblox-badges-container .badge-list > .list-item .asset-thumb-container {
      margin-left: 5px !important;
      transform: scale(0.642857) !important;
      transform-origin: 0 0 !important;
      margin-bottom: -50px !important;
      filter: grayscale(1) contrast(1.2) brightness(0.2) !important;
  }
  .dark-theme.btr-profile .btr-games-list .btr-game-button {
    background-color: #0606064a !important;
    border-color: #1010104f !important;
  }
  .chat-container .chat-main .chat-header {
      background-color: #0e0e0e !important;
  }
  .chat-main {
      box-shadow: none !important;
  }
  .rbx-divider {
      height: 0 !important;
      background-color: transparent !important;
      overflow: hidden !important;
  }
  .dark-theme .chat-main {
      background-color: #000 !important;
      color: #fff !important;
  }
  .dark-theme .rbx-left-col {
      box-shadow: 0 0 8px rgba(0, 0, 0, 0.3) !important;
      background-color: #000 !important;
  }
  .dark-theme .rbx-header {
      background-color: #000 !important;
      border-bottom: 1px solid #1a1a1a !important;
  }
  .dark-theme .menu-vertical {
      background-color: #080808 !important;
      color: #fff !important;
  }
  .dark-theme .content,
  .dark-theme .section-content,
  .dark-theme .stack .stack-list .stack-row {
      background-color: rgba(0, 0, 0, 0.45) !important;
      color: #fff !important;
      border-radius: 5px !important;
  }
  .dark-theme .stack .card-list .card-item {
      background-color: transparent !important;
      border-radius: 5px !important;
  }
  .dark-theme .rbx-tab .rbx-tab-heading {
      background-color: transparent !important;
      color: #fff !important;
      border-radius: 5px !important;
  }
  .dark-theme .rbx-tabs-vertical .category-tabs .menu-vertical {
      background-color: rgba(0, 0, 0, 0.51) !important;
      color: #fff !important;
      border-radius: 5px !important;
  }
  .dark-theme .asset-thumb-container {
      background-color: rgba(0, 0, 0, 0.28) !important;
      border: none !important;
  }
  .dark-theme .thumbnail-2d-container {
      border: none !important;
      background-color: rgba(0, 0, 0, 0.39) !important;
      border-color: #393b3d !important;
  }
  .dark-theme {
      background-color: #000 !important;
      color: #fff !important;
      background-size: 100% 100% !important;
  }
  
  /* Extension Dark Theming */
  
  .dark-theme .btn-control-md {
    background-color: rgba(54, 54, 54, 0.12);
    border-color: var(--color-action-standard-border);
    color: var(--color-action-standard-foreground);
    border-radius: 8px;
  }
  
  #user-profile-header-bg .avatar-card-image {
    background-color: rgba(49, 49, 49, 0.08) !important;
  }
  .dark-theme .cover-gradient-overlay {
    background: transparent;
  }
  .bg-action-standard {
    background-color: rgba(51, 51, 51, 0.12);
  }
  .bg-shift-300 {
    background-color: rgba(60, 60, 60, 0.12);
  }
  .dark-theme .btn-control-md {
    background-color: rgba(45, 45, 45, 0.12);
  }
  .dark-theme .input-group .input-field {
    background-color: rgba(51, 51, 51, 0.08);
  }
  .dark-theme .rbx-tabs-horizontal .nav-tabs {
    color: #f7f7f8;
    background-color: #090909;
    border-radius: 9px;
  }
  dark-theme .stack .card-list .player-thumbnails-container .player-avatar.hidden-players-placeholder {
    background-color: #202020;
  }
  .dark-theme .btn-control-xs {
    color: #d7d7d7;
    background-color: rgba(191, 191, 191, 0.12);
    border-color: transparent;
    border-radius: 8px;
  }
  
  /* Extension Dark Theming */
}
